class PushBoxGame:
    # Symbolic constants for map characters
    WALL = "#"
    PLAYER = "O"
    TARGET = "G"
    BOX = "X"

    # Direction deltas: (row_delta, col_delta)
    MOVEMENTS = {
        "w": (-1, 0),
        "s": (1, 0),
        "a": (0, -1),
        "d": (0, 1),
    }

    def __init__(self, map_):
        self.map = map_
        self.player_row = 0
        self.player_col = 0
        self.targets = []
        self.boxes = []
        self.target_count = 0
        self.is_game_over = False

        self.init_game()

    def init_game(self):
        for row in range(len(self.map)):
            for col in range(len(self.map[row])):
                cell = self.map[row][col]
                if cell == self.PLAYER:
                    self.player_row = row
                    self.player_col = col
                elif cell == self.TARGET:
                    self.targets.append((row, col))
                    self.target_count += 1
                elif cell == self.BOX:
                    self.boxes.append((row, col))

    def check_win(self):
        box_on_target_count = self.count_boxes_on_targets()
        if box_on_target_count == self.target_count:
            self.is_game_over = True
        return self.is_game_over

    def count_boxes_on_targets(self):
        return sum(1 for box in self.boxes if box in self.targets)

    def move(self, direction):
        row_delta, col_delta = self.MOVEMENTS[direction]
        new_player_row = self.player_row + row_delta
        new_player_col = self.player_col + col_delta

        if not self.is_wall(new_player_row, new_player_col):
            if self.is_box_at(new_player_row, new_player_col):
                self.try_push_box(new_player_row, new_player_col, row_delta, col_delta)
            else:
                self.move_player(new_player_row, new_player_col)

        return self.check_win()

    def is_wall(self, row, col):
        return self.map[row][col] == self.WALL

    def is_box_at(self, row, col):
        return (row, col) in self.boxes

    def try_push_box(self, new_player_row, new_player_col, row_delta, col_delta):
        new_box_row = new_player_row + row_delta
        new_box_col = new_player_col + col_delta

        if not self.is_wall(new_box_row, new_box_col):
            self.boxes.remove((new_player_row, new_player_col))
            self.boxes.append((new_box_row, new_box_col))
            self.move_player(new_player_row, new_player_col)

    def move_player(self, new_player_row, new_player_col):
        self.player_row = new_player_row
        self.player_col = new_player_col
